    input [7:0] a,
    input [7:0] b,
    output reg greater_than
);

    always @(*) begin
        if (a > b) begin
            greater_than = 1;
        end else begin
            greater_than = 0;
        end
    end

endmodule
module counter_module (
    input clk,
    input reset,
    input enable,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else if (enable) begin
            count <= count + 1;
        end
    end

endmodule
module control_logic_module (
    input [7:0] a,
    input [7:0] b,
    input greater_than,
    output reg equal,
    output reg enable
);

    always @(*) begin
        if (a > b) begin
            equal = 0;
            enable = 1;
        end else if (a < b) begin
            equal = 0;
            enable = 0;
        end else begin
            equal = 1;
            enable = 1;
        end
    end

endmodule
