    input [6:0] ecc_in,
    input tag_in,
    input valid_in,
    input control_tag_in,
    input error_in,
    input dequeue_in,
    input por_req_in,
    input clk,
    input reset,
    output [31:0] data_out,
    output [6:0] ecc_out,
    output tag_out,
    output valid_out,
    output control_tag_out,
    output error_out,
    output dequeue_out,
