reg [6:0] ecc_reg;
reg tag_reg;
reg valid_reg;
reg control_tag_reg;
reg error_reg;
reg dequeue_reg;
reg por_req_reg;

always @(posedge clk) begin
    if (reset) begin
        data_reg <= 0;
        ecc_reg <= 0;
        tag_reg <= 0;
        valid_reg <= 0;
        control_tag_reg <= 0;
        error_reg <= 0;
        dequeue_reg <= 0;
        por_req_reg <= 1;
    end else begin
        if (por_req_in) begin
            por_req_reg <= 0;
        end
        if (control_tag_in) begin
            control_tag_reg <= 1;
        end else if (dequeue_in) begin
            control_tag_reg <= 0;
