            data_reg <= data_in;
            ecc_reg <= ecc_in;
            tag_reg <= tag_in;
            valid_reg <= 1;
        end
        if (dequeue_in) begin
            valid_reg <= 0;
            dequeue_reg <= 1;
        end
        if (error_in) begin
            error_reg <= 1;
        end
    end
