  case (current_state)
    S0: out = 2'b00;
    S1: out = 2'b01;
    S2: out = 2'b10;
    S3: out = 2'b11;
    S4: out = 2'b00;
    S5: out = 2'b01;
    S6: out = 2'b10;
    S7: out = 2'b11;
    default: out = 2'b00;
  endcase
end

// State register
always @(posedge clk) begin // Added clk as the clock signal
  current_state <= next_state;
end

endmodule

