module full_adder(
    input in1,
    input in2,
    input carry_in,
    output sum,
    output carry_out
);

assign sum = in1 ^ in2 ^ carry_in;
assign carry_out = (in1 & in2) | (in1 & carry_in) | (in2 & carry_in);

endmodule
